function validate([word1, word2]) {
  if (word2.length < 1 || word2.length >= word1.length) return 'Need 1 <= word2.length < word1.length.';
  if (word1.length > 300000) return 'word1 has at most 3 * 10^5 letters.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Both words use only lowercase English letters.';
  return null;
}

