function validSequence(word1, word2) {
  const n = word1.length;
  const m = word2.length;
  // suffix[i]: length of the longest suffix of word2 that is a subsequence of word1 from index i on.
  const suffix = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffix[i] = suffix[i + 1];
    if (suffix[i] < m && word1[i] === word2[m - 1 - suffix[i]]) {
      suffix[i]++;
    }
  }
  const sequence = [];
  let changed = false;
  for (let i = 0; i < n && sequence.length < m; i++) {
    const j = sequence.length;
    if (word1[i] === word2[j]) {
      sequence.push(i);
    } else if (!changed && suffix[i + 1] >= m - j - 1) {
      sequence.push(i);
      changed = true;
    }
  }
  return sequence.length === m ? sequence : [];
}

