function validSequence(word1, word2) {
  // Try increasing index lists in lexicographic order; the first one needing at most one change wins.
  const chosen = [];
  const search = (start, changes) => {
    if (chosen.length === word2.length) return true;
    for (let i = start; i < word1.length; i++) {
      const cost = changes + (word1[i] === word2[chosen.length] ? 0 : 1);
      if (cost > 1) continue;
      chosen.push(i);
      if (search(i + 1, cost)) return true;
      chosen.pop();
    }
    return false;
  };
  return search(0, 0) ? chosen : [];
}

