function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const large = size === 'large';
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const n = large ? 10000 : 2 + pick(9);
  const letters = alphabet.slice(0, large ? 2 + pick(25) : 1 + pick(3));
  const letter = () => letters[pick(letters.length)];
  const word1 = Array.from({ length: n }, letter).join('');
  const m = 1 + pick(n - 1);
  const changes = pick(3);
  if (changes === 0) return [word1, Array.from({ length: m }, letter).join('')];
  // Otherwise word2 spells a random subsequence of word1 with one change (always solvable) or two (often not).
  const indices = [...Array(n).keys()];
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [indices[i], indices[j]] = [indices[j], indices[i]];
  }
  const chars = indices.slice(0, m).sort((a, b) => a - b).map(i => word1[i]);
  for (let k = 0; k < changes; k++) chars[pick(m)] = alphabet[pick(26)];
  return [word1, chars.join('')];
}
